    // MARK: - PKCS7 Padding Validation (constant-time)
    private func validateAndStripPKCS7(_ plaintext: Data) -> Result<Data, ContractError> {
        guard plaintext.count > 0 && plaintext.count % blockSize == 0 else {
            return .failure(.invalidPayload)
        }

        let paddingByte = plaintext[plaintext.count - 1]
        let paddingLength = Int(paddingByte)

        // Constant-time validation: check all bytes, accumulate result
        var validPadding: UInt8 = 1

        // Validate padding length is in range
        let lengthValid: UInt8 = (paddingLength > 0 && paddingLength <= blockSize) ? 1 : 0
        validPadding &= lengthValid

        // Check all potential padding positions in constant time
        for i in 0..<blockSize {
            let idx = plaintext.count - 1 - i
            let isInPaddingRange: UInt8 = (i < paddingLength) ? 1 : 0
            let byteMatches: UInt8 = (plaintext[idx] == paddingByte) ? 1 : 0
            // Only require match if in padding range
            let check: UInt8 = isInPaddingRange & (byteMatches ^ 1)
            validPadding &= (check ^ 1)
        }

        // Do NOT branch differently based on padding validity vs other errors
        guard validPadding == 1 else {
            return .failure(.decryptionFailure)
        }

        let strippedData = plaintext.prefix(plaintext.count - paddingLength)
        return .success(Data(strippedData))
    }

    // MARK: - CBC Decryption
    private func decryptCBC(ciphertext: Data, iv: Data) -> Result<Data, ContractError> {
        guard ciphertext.count % blockSize == 0 else {
            return .failure(.invalidPayload)
        }

        var previousBlock = iv
        var plaintext = Data()
        let keyBytes = symmetricKey.withUnsafeBytes { Data($0) }

        for blockIndex in stride(from: 0, to: ciphertext.count, by: blockSize) {
            let currentBlock = ciphertext[blockIndex..<blockIndex + blockSize]
            let decryptedBlock = aesECBDecrypt(block: Data(currentBlock), key: keyBytes)

            // XOR with previous ciphertext block (or IV for first block)
            var xoredBlock = Data(count: blockSize)
            for i in 0..<blockSize {
                xoredBlock[i] = decryptedBlock[i] ^ previousBlock[i]
            }

            plaintext.append(xoredBlock)
            previousBlock = Data(currentBlock)
        }

        return .success(plaintext)
    }

