// MARK: - Reverse Proxy Response Handler
// The proxy maps contract execution results to HTTP responses
struct ProxyResponseMapper {

    /// Maps contract execution results to HTTP responses
    /// All decryption-related failures return the same status code
    static func mapToHTTPResponse(_ result: Result<Data, ContractError>) -> (statusCode: Int, body: Data?) {
        switch result {
        case .success(let data):
            return (200, data)
        case .failure(let error):
            switch error {
            case .invalidPayload:
                return (400, "Invalid payload format".data(using: .utf8))
            case .paddingInvalid, .decryptionFailure, .signatureInvalid:
                // Unified error response - no oracle distinguishability
                return (401, "Authentication failed".data(using: .utf8))
            case .ballotExpired:
                return (404, "Resource expired".data(using: .utf8))
            case .internalError:
                return (500, "Internal error".data(using: .utf8))
            }
        }
    }
}

// MARK: - Request Handler (called by reverse proxy)
func handleBallotVerification(requestBody: Data) -> (statusCode: Int, body: Data?) {
    guard requestBody.count >= 56 else {
        return ProxyResponseMapper.mapToHTTPResponse(.failure(.invalidPayload))
    }

    let iv = requestBody.prefix(16)
    let commitmentData = requestBody[16..<48]
    // Fixed: use loadUnaligned to avoid undefined behavior / traps on unaligned access
    let blockHeight = requestBody[48..<56].withUnsafeBytes { $0.loadUnaligned(as: UInt64.self) }
    let ciphertext = requestBody.suffix(from: 56)

    let ballot = EncryptedBallot(
        ciphertext: Data(ciphertext),
        iv: Data(iv),
        voterCommitment: Data(commitmentData),
        blockHeight: blockHeight
    )

    guard let keyMaterial = getContractKey() else {
        return ProxyResponseMapper.mapToHTTPResponse(.failure(.internalError))
    }

    let oracle = BallotDecryptionOracle(keyMaterial: keyMaterial)
    let result = oracle.verifyEncryptedBallot(ballot)

    return ProxyResponseMapper.mapToHTTPResponse(result)
}

// Fixed: do NOT return a hardcoded/predictable key (CWE-321).
// Load the key from a secure source (secure enclave / KMS / keychain).
// Fails safely (returns nil) if unavailable rather than using a constant key.
func getContractKey() -> Data? {
    // Example: retrieve from environment-provided secure store.
    // Replace with actual secure enclave / KMS retrieval in production.
    guard let hex = ProcessInfo.processInfo.environment["CONTRACT_KEY_HEX"],
          hex.count == 64 else {
        return nil
    }
    var data = Data()
    var index = hex.startIndex
    while index < hex.endIndex {
        let next = hex.index(index, offsetBy: 2)
        guard let byte = UInt8(hex[index..<next], radix: 16) else { return nil }
        data.append(byte)
        index = next
    }
    return data.count == 32 ? data : nil
}
